1	import { describe, it, expect } from "vitest";
2	import { render, screen, within } from "@testing-library/react";
3	import userEvent from "@testing-library/user-event";
4	import { axe } from "jest-axe";
5	import { CircleCheck } from "lucide-react";
6	import { StatCard } from "@/components/ui/StatCard";
7	import { StatusBadge } from "@/components/ui/StatusBadge";
8	import { DataTable, type Column } from "@/components/ui/DataTable";
