10	describe("StatCard", () => {
11	  it("shows a labeled number with no a11y violations", async () => {
12	    const { container } = render(
13	      <StatCard label="This week's earnings" value="$22.80" hint="2 sessions" />,
14	    );
15	    expect(screen.getByText("This week's earnings")).toBeInTheDocument();
16	    expect(screen.getByText("$22.80")).toBeInTheDocument();
17	    expect(await axe(container)).toHaveNoViolations();
18	  });
19	});
20	
21	describe("StatusBadge", () => {
22	  it("carries text (and icon), not colour alone", async () => {
23	    const { container } = render(
24	      <StatusBadge tone="success" icon={CircleCheck}>
25	        Approved
26	      </StatusBadge>,
27	    );
28	    expect(screen.getByText("Approved")).toBeInTheDocument();
29	    expect(await axe(container)).toHaveNoViolations();
30	  });
31	});
