33	interface Row {
34	  id: string;
35	  name: string;
36	  amount: number;
37	}
38	const ROWS: Row[] = [
39	  { id: "a", name: "Theo", amount: 2100 },
40	  { id: "b", name: "Maya", amount: 2400 },
41	  { id: "c", name: "Omar", amount: 1200 },
42	];
43	const COLUMNS: Column<Row>[] = [
44	  { key: "name", header: "Listener", sortable: true },
45	  {
46	    key: "amount",
47	    header: "Amount",
48	    align: "right",
49	    sortable: true,
50	    render: (r) => `$${(r.amount / 100).toFixed(2)}`,
51	    sortValue: (r) => r.amount,
52	  },
53	];
54	
55	describe("DataTable", () => {
56	  it("renders a semantic table with caption and column headers", async () => {
57	    const { container } = render(
58	      <DataTable
59	        caption="Recent payouts"
60	        columns={COLUMNS}
61	        rows={ROWS}
62	        getRowKey={(r) => r.id}
63	      />,
64	    );
65	    expect(screen.getByRole("table", { name: "Recent payouts" })).toBeInTheDocument();
66	    const headers = screen.getAllByRole("columnheader");
67	    expect(headers).toHaveLength(2);
68	    expect(headers[0]).toHaveAttribute("scope", "col");
69	    expect(await axe(container)).toHaveNoViolations();
70	  });
71	
72	  it("sorts on a header click and reflects aria-sort + announces it", async () => {
73	    const user = userEvent.setup();
74	    render(
75	      <DataTable
76	        caption="Recent payouts"
77	        columns={COLUMNS}
78	        rows={ROWS}
79	        getRowKey={(r) => r.id}
80	      />,
81	    );
82	
83	    // Sort by Amount ascending.
84	    await user.click(screen.getByRole("button", { name: /amount/i }));
85	    const amountHeader = screen
86	      .getAllByRole("columnheader")
87	      .find((h) => within(h).queryByRole("button", { name: /amount/i }))!;
88	    expect(amountHeader).toHaveAttribute("aria-sort", "ascending");
89	
90	    let firstRowCells = within(screen.getAllByRole("row")[1]).getAllByRole("cell");
91	    expect(firstRowCells[1]).toHaveTextContent("$12.00"); // smallest first
92	
93	    // Toggle to descending.
94	    await user.click(screen.getByRole("button", { name: /amount/i }));
95	    expect(amountHeader).toHaveAttribute("aria-sort", "descending");
96	    firstRowCells = within(screen.getAllByRole("row")[1]).getAllByRole("cell");
97	    expect(firstRowCells[1]).toHaveTextContent("$24.00"); // largest first
98	  });
99	});
